package com.alfa.device_ctrl;
import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.os.Bundle;import android.view.Gravity;import android.widget.Button;import android.widget.LinearLayout;import android.widget.TextView;
/** Native capability navigator; every action opens a real backend/evidence surface. */
public final class RuntimeToolsActivity extends Activity{private static final int BG=Color.rgb(19,19,21),PRIMARY=Color.rgb(171,199,255),MUTED=Color.rgb(193,198,213);@Override protected void onCreate(Bundle s){super.onCreate(s);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(BG);r.setPadding(dp(14),dp(14),dp(14),dp(14));r.addView(text("ALFA RUNTIME TOOLS",PRIMARY,16,true),new LinearLayout.LayoutParams(-1,dp(52)));add(r,"SECURITY DIAGNOSTIC","SELinux / seccomp / Shizuku / Rish evidence",()->startActivity(new Intent(this,SecurityDiagnosticActivity.class)));add(r,"PROJECT EXPLORER","SAF content URI explorer",()->startActivity(new Intent(this,ProjectExplorerActivity.class)));add(r,"PROJECT EDITOR / SOCKET","SAF editor + LocalSocket diagnostic",()->startActivity(new Intent(this,ProjectEditorSocketDiagnosticsActivity.class)));add(r,"TERMUX EXECUTION / API","RUN_COMMAND + real callback evidence",()->startActivity(new Intent(this,TermuxExecutionActivity.class)));add(r,"VFS / MOUNT POLICY","Runtime-bound VFS and mount evidence",()->startActivity(new Intent(this,RuntimeVfsPolicyActivity.class)));add(r,"SECURITY / POLICY","InteractiveSessionContract evidence",()->startActivity(new Intent(this,PolicyEvidenceActivity.class)));add(r,"APPEARANCE / LANGUAGE","DataStore-backed UI settings",()->startActivity(new Intent(this,AppearanceLanguageSettingsActivity.class)));add(r,"NOTIFICATIONS","POST_NOTIFICATIONS + FGS channel state",()->startActivity(new Intent(this,NotificationStateActivity.class)));add(r,"SPLIT TERMINAL","Multi-session PTY workspace",()->startActivity(new Intent(this,SplitTerminalActivity.class)));add(r,"FLOATING TERMINAL","Overlay permission, bubble, resize and opacity",()->startActivity(new Intent(this,FloatingTerminalActivity.class)));add(r,"EVIDENCE SHARING","content:// FileProvider export",()->startActivity(new Intent(this,EvidenceShareActivity.class)));setContentView(r);}private void add(LinearLayout r,String title,String detail,Runnable action){Button b=new Button(this);b.setText(title+"\n"+detail);b.setTextColor(MUTED);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setAllCaps(false);b.setMinHeight(dp(56));b.setOnClickListener(v->action.run());b.setContentDescription(title);r.addView(b,new LinearLayout.LayoutParams(-1,dp(64)));}private TextView text(String v,int c,int s,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextColor(c);t.setTextSize(s);if(b)t.setTypeface(android.graphics.Typeface.MONOSPACE,android.graphics.Typeface.BOLD);return t;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
